macro_rules! deps {
    () => {
        Interner!();
        BuiltinImplSource!();
        ParamEnv!();
        ParamEnvSource!();
    };
}

macro_rules! CandidateSource {
    () => {
        deps!();
        # [doc = " Possible ways the given goal can be proven."] # [derive_where (Clone , Copy , Hash , PartialEq , Debug ; I : Interner)] pub enum CandidateSource < I : Interner > { # [doc = " A user written impl."] # [doc = ""] # [doc = " ## Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " fn main() {"] # [doc = "     let x: Vec<u32> = Vec::new();"] # [doc = "     // This uses the impl from the standard library to prove `Vec<T>: Clone`."] # [doc = "     let y = x.clone();"] # [doc = " }"] # [doc = " ```"] Impl (I :: ImplId) , # [doc = " A builtin impl generated by the compiler. When adding a new special"] # [doc = " trait, try to use actual impls whenever possible. Builtin impls should"] # [doc = " only be used in cases where the impl cannot be manually be written."] # [doc = ""] # [doc = " Notable examples are auto traits, `Sized`, and `DiscriminantKind`."] # [doc = " For a list of all traits with builtin impls, check out the"] # [doc = " `EvalCtxt::assemble_builtin_impl_candidates` method."] BuiltinImpl (BuiltinImplSource) , # [doc = " An assumption from the environment. Stores a [`ParamEnvSource`], since we"] # [doc = " prefer non-global param-env candidates in candidate assembly."] # [doc = ""] # [doc = " ## Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " fn is_clone<T: Clone>(x: T) -> (T, T) {"] # [doc = "     // This uses the assumption `T: Clone` from the `where`-bounds"] # [doc = "     // to prove `T: Clone`."] # [doc = "     (x.clone(), x)"] # [doc = " }"] # [doc = " ```"] ParamEnv (ParamEnvSource) , # [doc = " If the self type is an alias type, e.g. an opaque type or a projection,"] # [doc = " we know the bounds on that alias to hold even without knowing its concrete"] # [doc = " underlying type."] # [doc = ""] # [doc = " More precisely this candidate is using the `n-th` bound in the `item_bounds` of"] # [doc = " the self type."] # [doc = ""] # [doc = " ## Examples"] # [doc = ""] # [doc = " ```rust"] # [doc = " trait Trait {"] # [doc = "     type Assoc: Clone;"] # [doc = " }"] # [doc = ""] # [doc = " fn foo<T: Trait>(x: <T as Trait>::Assoc) {"] # [doc = "     // We prove `<T as Trait>::Assoc` by looking at the bounds on `Assoc` in"] # [doc = "     // in the trait definition."] # [doc = "     let _y = x.clone();"] # [doc = " }"] # [doc = " ```"] AliasBound , # [doc = " A candidate that is registered only during coherence to represent some"] # [doc = " yet-unknown impl that could be produced downstream without violating orphan"] # [doc = " rules."] CoherenceUnknowable , }
    };
}

CandidateSource!();